-- BLOCK 2: PROC_M — ALL_ARGUMENTS 에서 동적 등록 (PKG 배포 전이면 As-is 파라미터로 임시 등록 + WARN)
DECLARE v_pkg VARCHAR2(128); v_obj VARCHAR2(128); v_n NUMBER;
