      INSERT INTO SCM_ADM_PROC_M (PROC_NM, COL_NM, COL_TP_CD, DATA_TP_CD, SORT_ORD, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE) VALUES ('PKG_SCP0122.P_SCP0122_GET_PLAN_ACTIVITY_MGMT', 'o_rc1', 'OUT', 'CURSOR', 4, '&V_USER_ID', SYSDATE, '&V_USER_ID', SYSDATE);
