  -- Plan Activity Mgmt / SAVE  ← As-is SCP0122_SAVE_PLAN_ACTIVITY_MGMT
  v_pkg := 'PKG_SCP0122'; v_obj := 'P_SCP0122_SAVE_PLAN_ACTIVITY_MGMT'; v_n := 0;
