DECLARE
    v_col_json CLOB := '[
        {"sht_nm":"Plan Activity Mgmt","col_nm":"AUTO_YN","col_lbl":"Auto Flag","sort_ord":10,"col_wth":100,"align":"C","visible":"Y","default_f":"Y","div_id":"ALL","input_tp":"S"},
        {"sht_nm":"Plan Activity Mgmt","col_nm":"CONFIRM_YN","col_lbl":"Confirm Flag","sort_ord":9,"col_wth":100,"align":"C","visible":"Y","default_f":"Y","div_id":"ALL","input_tp":"S"},
