        {"sht_nm":"Plan Activity Mgmt","col_nm":"OPMZ_ACTV_NAME","col_lbl":"Activity Name","sort_ord":6,"col_wth":200,"cell_tp":"FPComboBox","cell_cbo":"ActivityCode","align":"L","visible":"Y","default_f":"Y","div_id":"ALL","input_tp":"S"},
