        {"sht_nm":"Plan Activity Mgmt","col_nm":"OPMZ_PLAN_GR_NAME","col_lbl":"Plan Group","sort_ord":3,"col_wth":150,"align":"L","visible":"Y","default_f":"Y","div_id":"ALL","input_tp":"S"},
        {"sht_nm":"Plan Activity Mgmt","col_nm":"OPMZ_PRS_CD","col_lbl":"Process CD","sort_ord":2,"align":"C","visible":"Y","default_f":"Y","div_id":"ALL","input_tp":"S"},
