    VALUES ('SCP0122_PLAN_ACTIVITY_MGMT_SEARCH', 'PROC', NULL, 'SCP0122 Plan Activity Mgmt SEARCH', 'PKG_SCP0122.P_SCP0122_GET_PLAN_ACTIVITY_MGMT', 'Y', '&V_USER_ID', SYSDATE, '&V_USER_ID', SYSDATE)
  INTO SCM_ADM_API_M (API_ID, API_TP_CD, API_MSG_ID, API_MSG_DESC, API_URL, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE)
    VALUES ('SCP0122_PLAN_ACTIVITY_MGMT_SAVE', 'PROC', NULL, 'SCP0122 Plan Activity Mgmt SAVE', 'PKG_SCP0122.P_SCP0122_SAVE_PLAN_ACTIVITY_MGMT', 'Y', '&V_USER_ID', SYSDATE, '&V_USER_ID', SYSDATE)
